/****************************************************************************
 * VelaGuard ai_agent seed content (eMMC /data/agent).
 *
 * Writes default Skill markdown once; seeds LLM config.json when a build-time
 * key is provided and eMMC has no api_key yet.
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA

#include "agent_secrets.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static const char g_modbus_query_skill[] =
"# Modbus 实时查数（VelaGuard）\n"
"\n"
"## 何时使用\n"
"\n"
"用户问从站寄存器、温湿度、水浸、通信质量时，用 **run_shell** 调 NSH 只读工具。\n"
"\n"
"## 命令\n"
"\n"
"- 读保持寄存器：`vgmodbus -a <addr> -r <reg> -c <count> -n 1 -i 0`\n"
"- 帧统计：`vgstats dump <addr>`\n"
"- 配置摘要：`vgcfg dump`\n"
"\n"
"## 示例\n"
"\n"
"从站 1 温湿度 reg0..1：\n"
"```\n"
"vgmodbus -a 1 -r 0 -c 2 -n 1 -i 0\n"
"```\n"
"\n"
"禁止写操作、禁止 mkfs/reboot。只读。\n";

static int write_if_missing(const char *path, const char *body)
{
  int fd;

  fd = open(path, O_RDONLY);
  if (fd >= 0)
    {
      close(fd);
      return 0;
    }

  fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0644);
  if (fd < 0)
    {
      return -errno;
    }

  if (write(fd, body, strlen(body)) != (ssize_t)strlen(body))
    {
      close(fd);
      return -EIO;
    }

  close(fd);
  return 0;
}

static void wait_for_data_mount(void)
{
  struct stat st;
  int i;

  for (i = 0; i < 50; i++)
    {
      if (stat("/data", &st) == 0)
        {
          return;
        }

      usleep(100000);
    }
}

static bool config_has_api_key(void)
{
  int fd;
  char buf[640];
  ssize_t n;
  const char *p;
  const char *val;

  fd = open("/data/agent/config/config.json", O_RDONLY);
  if (fd < 0)
    {
      return false;
    }

  n = read(fd, buf, sizeof(buf) - 1);
  close(fd);
  if (n <= 0)
    {
      return false;
    }

  buf[n] = '\0';
  p = strstr(buf, "\"api_key\"");
  if (p == NULL)
    {
      return false;
    }

  p = strchr(p, ':');
  if (p == NULL)
    {
      return false;
    }

  p++;
  while (*p == ' ' || *p == '\t')
    {
      p++;
    }

  if (*p != '"')
    {
      return false;
    }

  val = p + 1;
  return (val[0] != '\0' && val[0] != '"');
}

static int json_escape(const char *in, char *out, size_t outsz)
{
  size_t o = 0;

  if (outsz == 0)
    {
      return -EINVAL;
    }

  for (; *in != '\0'; in++)
    {
      char c = *in;
      if (c == '"' || c == '\\')
        {
          if (o + 2 >= outsz)
            {
              return -ENOSPC;
            }

          out[o++] = '\\';
        }

      if (o + 1 >= outsz)
        {
          return -ENOSPC;
        }

      out[o++] = c;
    }

  out[o] = '\0';
  return 0;
}

static void seed_llm_config_if_needed(void)
{
  char key_esc[192];
  char backend[512];
  char body[1024];
  int fd;
  int ret;

  if (VG_AGENT_LLM_API_KEY[0] == '\0')
    {
      return;
    }

  if (config_has_api_key())
    {
      return;
    }

  ret = mkdir("/data/agent/config", 0700);
  if (ret < 0 && errno != EEXIST)
    {
      return;
    }

  ret = json_escape(VG_AGENT_LLM_API_KEY, key_esc, sizeof(key_esc));
  if (ret < 0)
    {
      return;
    }

  snprintf(backend, sizeof(backend),
           "{\\\"host\\\":\\\"%s\\\",\\\"path\\\":\\\"%s\\\","
           "\\\"port\\\":\\\"%s\\\",\\\"api_key\\\":\\\"%s\\\","
           "\\\"model\\\":\\\"%s\\\",\\\"priority\\\":0,\\\"cost_tier\\\":1}",
           VG_AGENT_LLM_HOST, VG_AGENT_LLM_PATH, VG_AGENT_LLM_PORT,
           key_esc, VG_AGENT_LLM_MODEL);

  snprintf(body, sizeof(body),
           "{"
           "\"llm_host\":\"%s\","
           "\"llm_path\":\"%s\","
           "\"llm_port\":\"%s\","
           "\"model\":\"%s\","
           "\"api_key\":\"%s\","
           "\"llm_backend_0\":\"%s\""
           "}",
           VG_AGENT_LLM_HOST, VG_AGENT_LLM_PATH, VG_AGENT_LLM_PORT,
           VG_AGENT_LLM_MODEL, key_esc, backend);

  fd = open("/data/agent/config/config.json",
            O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return;
    }

  if (write(fd, body, strlen(body)) != (ssize_t)strlen(body))
    {
      close(fd);
      return;
    }

  close(fd);
}

void vg_agent_seed_content(void)
{
  wait_for_data_mount();
