/****************************************************************************
 * app/velaguard/vg_discover.h
 *
 * Modbus bus discovery @ fixed 9600: address scan, register probe, point table.
 ****************************************************************************/

#ifndef __APP_VELAGUARD_VG_DISCOVER_H
#define __APP_VELAGUARD_VG_DISCOVER_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define VG_DISCOVER_MAX_SLAVES   32
#define VG_DISCOVER_MAX_BLOCKS   64
#define VG_DISCOVER_MAX_POINTS   64
#define VG_DISCOVER_BLOCK_STEP   16
#define VG_DISCOVER_PROBE_QTY    16

struct vg_scan_hit
{
  uint8_t addr;
  bool    alive;
};

struct vg_reg_block
{
  uint8_t  addr;
  uint8_t  fc;
  uint16_t start;
  uint16_t count;
  uint16_t sample[4];
};

struct vg_point_entry
{
  uint8_t  addr;
  uint8_t  fc;
  uint16_t reg;
  uint16_t qty;
  char     tag[24];
  char     dtype[16];
  float    scale;
  char     unit[8];
};

struct vg_discover_summary
{
  int      baud;
  char     devpath[64];
  int      n_hits;
  struct vg_scan_hit hits[VG_DISCOVER_MAX_SLAVES];
  int      n_blocks;
  struct vg_reg_block blocks[VG_DISCOVER_MAX_BLOCKS];
  int      n_points;
  struct vg_point_entry points[VG_DISCOVER_MAX_POINTS];
};

void vg_discover_reset(struct vg_discover_summary *sum);

int vg_bus_scan(FAR struct vg_discover_summary *sum,
                FAR const char *devpath,
                int baud, int addr_min, int addr_max, int inter_ms);

int vg_reg_probe_slave(FAR struct vg_discover_summary *sum,
                       FAR const char *devpath, int baud,
                       uint8_t addr, int fc_filter, int reg_max);

int vg_point_table_infer(FAR struct vg_discover_summary *sum);

int vg_point_table_write_candidate(FAR const struct vg_discover_summary *sum,
                                   FAR const char *path);

int vg_point_table_apply(FAR const struct vg_discover_summary *sum,
                         FAR const char *points_path,
                         FAR const char *config_basedir,
                         bool confirm);

int vg_discover_test_read(FAR const char *devpath, int baud,
                          uint8_t addr, uint16_t reg, uint16_t qty,
                          FAR uint16_t *out);

/* Host-testable decode helpers */

float vg_discover_decode_int16_scaled(int16_t raw, float scale);
bool  vg_discover_parse_addr_range(FAR const char *spec,
                                   int *min_out, int *max_out);

#endif /* __APP_VELAGUARD_VG_DISCOVER_H */

/****************************************************************************
 * app/velaguard/vg_discover_modbus.c
 *
 * Shared nanoMODBUS session for discovery (internal).
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <string.h>

#include "modbus_port_openvela.h"
#include "nanomodbus.h"

#define VG_DISC_READ_TO_MS   500
#define VG_DISC_BYTE_TO_MS   50
#define VG_DISC_MAX_REGS     16

struct vg_disc_nmbs
{
  struct vg_modbus_port_s port;
  nmbs_t                  nmbs;
  bool                    ready;
};

static int vg_disc_nmbs_open(FAR struct vg_disc_nmbs *s, FAR const char *dev)
{
  nmbs_platform_conf pc;
  nmbs_error err;

  if (s == NULL || dev == NULL)
    {
      return -EINVAL;
    }

  memset(s, 0, sizeof(*s));
  s->port.fd = -1;

  if (vg_modbus_port_open(&s->port, dev) < 0)
    {
      return -errno;
    }

  vg_modbus_port_bind(&s->port, &pc);
  err = nmbs_client_create(&s->nmbs, &pc);
  if (err != NMBS_ERROR_NONE)
    {
      vg_modbus_port_close(&s->port);
      return -EIO;
    }

  nmbs_set_read_timeout(&s->nmbs, VG_DISC_READ_TO_MS);
  nmbs_set_byte_timeout(&s->nmbs, VG_DISC_BYTE_TO_MS);
  s->ready = true;
  return 0;
}

static void vg_disc_nmbs_close(FAR struct vg_disc_nmbs *s)
{
  if (s == NULL || !s->ready)
    {
      return;
    }

  vg_modbus_port_close(&s->port);
  s->ready = false;
}

static nmbs_error vg_disc_read_holding(FAR struct vg_disc_nmbs *s,
                                       uint8_t addr, uint16_t start,
                                       uint16_t qty, FAR uint16_t *regs)
{
  if (!s->ready || qty == 0 || qty > VG_DISC_MAX_REGS)
    {
      return NMBS_ERROR_INVALID_ARGUMENT;
    }

  nmbs_set_destination_rtu_address(&s->nmbs, addr);
  return nmbs_read_holding_registers(&s->nmbs, start, qty, regs);
}

static nmbs_error vg_disc_read_input(FAR struct vg_disc_nmbs *s,
                                     uint8_t addr, uint16_t start,
                                     uint16_t qty, FAR uint16_t *regs)
{
  if (!s->ready || qty == 0 || qty > VG_DISC_MAX_REGS)
    {
      return NMBS_ERROR_INVALID_ARGUMENT;
    }

  nmbs_set_destination_rtu_address(&s->nmbs, addr);
  return nmbs_read_input_registers(&s->nmbs, start, qty, regs);
}

int vg_discover_test_read(FAR const char *devpath, int baud,
                          uint8_t addr, uint16_t reg, uint16_t qty,
                          FAR uint16_t *out)
{
  struct vg_disc_nmbs s;
  nmbs_error err;

  (void)baud;

  if (devpath == NULL || out == NULL || addr == 0)
    {
      return -EINVAL;
    }

  if (vg_disc_nmbs_open(&s, devpath) != 0)
    {
      return -errno;
    }

  memset(out, 0, sizeof(uint16_t) * qty);
  err = vg_disc_read_holding(&s, addr, reg, qty, out);
  vg_disc_nmbs_close(&s);

  return (err == NMBS_ERROR_NONE) ? 0 : -EIO;
}

int vg_bus_scan(FAR struct vg_discover_summary *sum,
                FAR const char *devpath,
                int baud, int addr_min, int addr_max, int inter_ms)
{
  struct vg_disc_nmbs s;
  int addr;
  int n = 0;

  if (sum == NULL || devpath == NULL || addr_min < 1 || addr_max > 247 ||
      addr_min > addr_max)
    {
      return -EINVAL;
    }

  if (vg_disc_nmbs_open(&s, devpath) != 0)
    {
      return -errno;
    }

  sum->baud = baud;
  snprintf(sum->devpath, sizeof(sum->devpath), "%s", devpath);
  sum->n_hits = 0;

  for (addr = addr_min; addr <= addr_max; addr++)
    {
      uint16_t reg;
      nmbs_error err;

      if (sum->n_hits >= VG_DISCOVER_MAX_SLAVES)
        {
          break;
        }

      err = vg_disc_read_holding(&s, (uint8_t)addr, 0, 1, &reg);
      if (err == NMBS_ERROR_NONE)
        {
          sum->hits[sum->n_hits].addr  = (uint8_t)addr;
          sum->hits[sum->n_hits].alive = true;
          sum->n_hits++;
          n++;
        }

      if (inter_ms > 0)
        {
          usleep((useconds_t)inter_ms * 1000);
        }
    }

  vg_disc_nmbs_close(&s);
  return n;
}

int vg_reg_probe_slave(FAR struct vg_discover_summary *sum,
                       FAR const char *devpath, int baud,
                       uint8_t addr, int fc_filter, int reg_max)
{
  struct vg_disc_nmbs s;
  int fail_streak = 0;
  uint16_t start;

  if (sum == NULL || devpath == NULL || addr == 0)
    {
      return -EINVAL;
    }

  if (reg_max <= 0)
    {
      reg_max = 120;
    }

  if (vg_disc_nmbs_open(&s, devpath) != 0)
    {
      return -errno;
    }

  sum->baud = baud;
  snprintf(sum->devpath, sizeof(sum->devpath), "%s", devpath);

  for (start = 0; start < (uint16_t)reg_max && fail_streak < 3; )
    {
      uint16_t regs[VG_DISC_PROBE_QTY];
      nmbs_error err;
      int do_holding = (fc_filter == 0 || fc_filter == 3);
      int do_input   = (fc_filter == 0 || fc_filter == 4);

      if (sum->n_blocks >= VG_DISCOVER_MAX_BLOCKS)
        {
          break;
        }

      memset(regs, 0, sizeof(regs));
      err = NMBS_ERROR_TRANSPORT;

      if (do_holding)
        {
          err = vg_disc_read_holding(&s, addr, start, VG_DISC_PROBE_QTY, regs);
          if (err == NMBS_ERROR_NONE)
            {
              FAR struct vg_reg_block *b = &sum->blocks[sum->n_blocks];

              b->addr   = addr;
              b->fc     = 3;
              b->start  = start;
              b->count  = VG_DISC_PROBE_QTY;
              memcpy(b->sample, regs, sizeof(b->sample));
              sum->n_blocks++;
              fail_streak = 0;
              start += VG_DISC_BLOCK_STEP;
              continue;
            }
        }

      if (do_input)
        {
          err = vg_disc_read_input(&s, addr, start, VG_DISC_PROBE_QTY, regs);
          if (err == NMBS_ERROR_NONE)
            {
              FAR struct vg_reg_block *b = &sum->blocks[sum->n_blocks];

              b->addr   = addr;
              b->fc     = 4;
              b->start  = start;
              b->count  = VG_DISC_PROBE_QTY;
              memcpy(b->sample, regs, sizeof(b->sample));
              sum->n_blocks++;
              fail_streak = 0;
              start += VG_DISC_BLOCK_STEP;
              continue;
            }
        }

      fail_streak++;
      start += VG_DISC_BLOCK_STEP;
    }

  vg_disc_nmbs_close(&s);
  return sum->n_blocks;
}

/****************************************************************************
 * app/velaguard/vg_point_table.c
 *
 * Point inference, JSON export, state persistence, apply.
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "vg_discover.h"

#ifdef CONFIG_VG_CONFIG_STORE
#include "vg_config_store.h"
#endif

#define VG_DISC_STATE_MAGIC  0x56474453u
#define VG_DISC_STATE_PATH   "/data/velaguard/discover/discover_state.bin"

struct vg_disc_state_file
{
  uint32_t magic;
  struct vg_discover_summary sum;
};

static struct vg_discover_summary g_sum;

struct vg_discover_summary *vg_discover_state(void)
{
  return &g_sum;
}

void vg_discover_reset(FAR struct vg_discover_summary *sum)
{
  if (sum != NULL)
    {
      memset(sum, 0, sizeof(*sum));
    }
}

float vg_discover_decode_int16_scaled(int16_t raw, float scale)
{
  return (float)raw * scale;
}

bool vg_discover_parse_addr_range(FAR const char *spec,
                                    int *min_out, int *max_out)
{
  int a;
  int b;
  char dash;

  if (spec == NULL || min_out == NULL || max_out == NULL)
    {
      return false;
    }

  if (strchr(spec, '-') != NULL)
    {
      if (sscanf(spec, "%d-%d", &a, &b) != 2)
        {
          return false;
        }
    }
  else
    {
      a = b = (int)strtol(spec, NULL, 0);
    }

  if (a < 1 || b > 247 || a > b)
    {
      return false;
    }

  *min_out = a;
  *max_out = b;
  return true;
}

static int mkdir_p(FAR const char *path)
{
  char tmp[128];
  char *p;
  size_t len;

  if (path == NULL)
    {
      return -EINVAL;
    }

  snprintf(tmp, sizeof(tmp), "%s", path);
  len = strlen(tmp);
  if (len == 0)
    {
      return -EINVAL;
    }

  for (p = tmp + 1; *p != '\0'; p++)
    {
      if (*p == '/')
        {
          *p = '\0';
          (void)mkdir(tmp, 0755);
          *p = '/';
        }
    }

  return mkdir(tmp, 0755);
}

int vg_discover_state_save(FAR const struct vg_discover_summary *sum,
                           FAR const char *path)
{
  struct vg_disc_state_file sf;
  int fd;
  ssize_t n;
  FAR const char *out = (path != NULL && path[0] != '\0') ?
                        path : VG_DISC_STATE_PATH;

  if (sum == NULL)
    {
      return -EINVAL;
    }

  mkdir_p("/data/velaguard/discover");

  sf.magic = VG_DISC_STATE_MAGIC;
  memcpy(&sf.sum, sum, sizeof(sf.sum));

  fd = open(out, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0)
    {
      return -errno;
    }

  n = write(fd, &sf, sizeof(sf));
  close(fd);

  return (n == (ssize_t)sizeof(sf)) ? 0 : -EIO;
}

int vg_discover_state_load(FAR struct vg_discover_summary *sum,
                           FAR const char *path)
{
  struct vg_disc_state_file sf;
  int fd;
  ssize_t n;
  FAR const char *in = (path != NULL && path[0] != '\0') ?
                       path : VG_DISC_STATE_PATH;

  if (sum == NULL)
    {
      return -EINVAL;
    }

  fd = open(in, O_RDONLY);
  if (fd < 0)
    {
      return -errno;
    }

  n = read(fd, &sf, sizeof(sf));
  close(fd);

  if (n != (ssize_t)sizeof(sf) || sf.magic != VG_DISC_STATE_MAGIC)
    {
      return -EINVAL;
    }

  memcpy(sum, &sf.sum, sizeof(*sum));
  return 0;
}

static void add_point(FAR struct vg_discover_summary *sum,
                      uint8_t addr, uint8_t fc, uint16_t reg,
                      FAR const char *tag, FAR const char *dtype,
                      float scale, FAR const char *unit)
{
  FAR struct vg_point_entry *p;

  if (sum->n_points >= VG_DISCOVER_MAX_POINTS)
    {
      return;
    }

  p = &sum->points[sum->n_points++];
  p->addr = addr;
  p->fc   = fc;
  p->reg  = reg;
  p->qty  = 1;
  snprintf(p->tag, sizeof(p->tag), "%s", tag);
  snprintf(p->dtype, sizeof(p->dtype), "%s", dtype);
  p->scale = scale;
  snprintf(p->unit, sizeof(p->unit), "%s", unit);
}

int vg_point_table_infer(FAR struct vg_discover_summary *sum)
{
  int i;

  if (sum == NULL)
    {
      return -EINVAL;
    }

  sum->n_points = 0;

  for (i = 0; i < sum->n_blocks; i++)
    {
      FAR struct vg_reg_block *b = &sum->blocks[i];
      int tag_idx = 0;

      if (b->count == 0)
        {
          continue;
        }

      for (tag_idx = 0; tag_idx < (int)b->count && tag_idx < 4; tag_idx++)
        {
          char tag[24];
          float scaled;

          scaled = vg_discover_decode_int16_scaled((int16_t)b->sample[tag_idx],
                                                   0.1f);
          snprintf(tag, sizeof(tag), "s%u_r%u_%d",
                   (unsigned)b->addr,
                   (unsigned)(b->start + (uint16_t)tag_idx), tag_idx);

          if (scaled >= -50.0f && scaled <= 120.0f)
            {
              add_point(sum, b->addr, b->fc,
                        (uint16_t)(b->start + (uint16_t)tag_idx),
                        tag, "int16", 0.1f, (tag_idx == 0) ? "C" : "%RH");
            }
          else
            {
              add_point(sum, b->addr, b->fc,
                        (uint16_t)(b->start + (uint16_t)tag_idx),
                        tag, "uint16", 1.0f, "");
            }
        }
    }

  return sum->n_points;
}

int vg_point_table_write_candidate(FAR const struct vg_discover_summary *sum,
                                     FAR const char *path)
{
  FILE *fp;
  int i;
  FAR const char *out = path;

  if (sum == NULL || out == NULL)
    {
      return -EINVAL;
    }

  mkdir_p("/data/velaguard/discover");

  fp = fopen(out, "w");
  if (fp == NULL)
    {
      return -errno;
    }

  fprintf(fp,
          "{\"schema_version\":1,\"bus\":{\"device\":\"%s\",\"baud\":%d},"
          "\"hits\":[",
          sum->devpath, sum->baud);

  for (i = 0; i < sum->n_hits; i++)
    {
      fprintf(fp, "%s%u", (i > 0) ? "," : "",
              (unsigned)sum->hits[i].addr);
    }

  fprintf(fp, "],\"points\":[");

  for (i = 0; i < sum->n_points; i++)
    {
      FAR const struct vg_point_entry *p = &sum->points[i];

      fprintf(fp,
              "%s{\"tag\":\"%s\",\"addr\":%u,\"fc\":%u,\"reg\":%u,"
              "\"qty\":%u,\"dtype\":\"%s\",\"scale\":%.3f,\"unit\":\"%s\"}",
              (i > 0) ? "," : "",
              p->tag, (unsigned)p->addr, (unsigned)p->fc,
              (unsigned)p->reg, (unsigned)p->qty,
              p->dtype, (double)p->scale, p->unit);
    }

  fprintf(fp, "]}\n");
  fclose(fp);
  return 0;
}

int vg_point_table_apply(FAR const struct vg_discover_summary *sum,
                         FAR const char *points_path,
                         FAR const char *config_basedir,
                         bool confirm)
{
  if (sum == NULL || points_path == NULL)
    {
      return -EINVAL;
    }

  if (!confirm)
    {
      printf("vgdiscover: dry-run apply → %d points to %s (use --confirm)\n",
             sum->n_points, points_path);
      return 0;
    }

  if (vg_point_table_write_candidate(sum, points_path) != 0)
    {
      return -EIO;
    }

#ifdef CONFIG_VG_CONFIG_STORE
  if (config_basedir != NULL)
    {
      struct vg_config cfg;
      int ret;

      vg_config_set_basedir(config_basedir);
      vg_config_factory_default(&cfg);
      snprintf(cfg.device_name, sizeof(cfg.device_name), "discovered");
      ret = vg_config_commit(&cfg);
      if (ret != 0)
        {
          printf("vgdiscover: vg_config_commit failed %d (%s)\n",
                 ret, vg_config_last_error());
          return ret;
        }
    }
#else
  (void)config_basedir;
#endif

  printf("vgdiscover: applied %d points → %s\n", sum->n_points, points_path);
  return 0;
}

/****************************************************************************
 * app/velaguard/vgdiscover.c
 *
 * NSH: Modbus bus discovery @ 9600 — scan, probe, dump, test-read, apply.
 ****************************************************************************/

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <nuttx/config.h>

#include "vg_discover.h"

#ifndef CONFIG_VG_DISCOVER_DEVPATH
#  define CONFIG_VG_DISCOVER_DEVPATH "/dev/rs485"
#endif

#ifndef CONFIG_VG_DISCOVER_BAUD
#  define CONFIG_VG_DISCOVER_BAUD 9600
#endif

#ifndef CONFIG_VG_DISCOVER_ADDR_MIN
#  define CONFIG_VG_DISCOVER_ADDR_MIN 1
#endif

#ifndef CONFIG_VG_DISCOVER_ADDR_MAX
#  define CONFIG_VG_DISCOVER_ADDR_MAX 32
#endif

#ifndef CONFIG_VG_DISCOVER_INTER_MS
#  define CONFIG_VG_DISCOVER_INTER_MS 5
#endif

#ifndef CONFIG_VG_DISCOVER_REG_MAX
#  define CONFIG_VG_DISCOVER_REG_MAX 120
#endif

#ifndef CONFIG_VG_DISCOVER_CANDIDATE_PATH
#  define CONFIG_VG_DISCOVER_CANDIDATE_PATH \
          "/data/velaguard/discover/point_table_candidate.json"
#endif

#ifndef CONFIG_VG_DISCOVER_POINTS_PATH
#  define CONFIG_VG_DISCOVER_POINTS_PATH "/data/velaguard/config/points.json"
#endif

#ifndef CONFIG_VG_CONFIG_BASEDIR
#  define CONFIG_VG_CONFIG_BASEDIR "/data/velaguard/config"
#endif

int vg_discover_state_save(FAR const struct vg_discover_summary *sum,
                           FAR const char *path);
int vg_discover_state_load(FAR struct vg_discover_summary *sum,
                           FAR const char *path);

static void usage(FAR const char *prog)
{
  printf("Usage:\n");
  printf("  %s scan [-a min-max]     # fixed %d baud\n", prog,
         CONFIG_VG_DISCOVER_BAUD);
  printf("  %s probe -a <addr> [-t 3|4|both]\n", prog);
  printf("  %s dump [-o path]\n", prog);
  printf("  %s test-read -a <addr> -r <reg> [-c qty]\n", prog);
  printf("  %s apply [--confirm]\n", prog);
}

int main(int argc, char *argv[])
{
  struct vg_discover_summary sum;
  FAR const char *dev = CONFIG_VG_DISCOVER_DEVPATH;
  int ret;

  if (argc < 2)
    {
      usage(argv[0]);
      return 1;
    }

  vg_discover_reset(&sum);

  if (strcmp(argv[1], "scan") == 0)
    {
      int amin = CONFIG_VG_DISCOVER_ADDR_MIN;
      int amax = CONFIG_VG_DISCOVER_ADDR_MAX;
      int i;

      if (argc >= 4 && strcmp(argv[2], "-a") == 0)
        {
          if (!vg_discover_parse_addr_range(argv[3], &amin, &amax))
            {
              fprintf(stderr, "vgdiscover: bad -a range\n");
              return 1;
            }
        }

      printf("vgdiscover: scan %s @%d addr %d..%d\n",
             dev, CONFIG_VG_DISCOVER_BAUD, amin, amax);

      ret = vg_bus_scan(&sum, dev, CONFIG_VG_DISCOVER_BAUD,
                        amin, amax, CONFIG_VG_DISCOVER_INTER_MS);
      if (ret < 0)
        {
          fprintf(stderr, "vgdiscover: scan failed %d\n", ret);
          return 1;
        }

      printf("vgdiscover: found %d slave(s):\n", sum.n_hits);
      for (i = 0; i < sum.n_hits; i++)
        {
          printf("  addr=%u\n", (unsigned)sum.hits[i].addr);
        }

      if (vg_discover_state_save(&sum, NULL) != 0)
        {
          fprintf(stderr, "vgdiscover: state save failed\n");
        }

      return (sum.n_hits > 0) ? 0 : 1;
    }

  if (strcmp(argv[1], "probe") == 0)
    {
      uint8_t addr = 0;
      int fc = 0;
      int opt;

      optind = 2;
      while ((opt = getopt(argc, argv, "a:t:")) != ERROR)
        {
          switch (opt)
            {
              case 'a':
                addr = (uint8_t)strtol(optarg, NULL, 0);
                break;

              case 't':
                if (strcmp(optarg, "3") == 0)
                  {
                    fc = 3;
                  }
                else if (strcmp(optarg, "4") == 0)
                  {
                    fc = 4;
                  }
                else if (strcmp(optarg, "both") == 0)
                  {
                    fc = 0;
                  }
                else
                  {
                    fprintf(stderr, "vgdiscover: -t must be 3, 4, or both\n");
                    return 1;
                  }
                break;

              default:
                usage(argv[0]);
                return 1;
            }
        }

      if (addr == 0)
        {
          fprintf(stderr, "vgdiscover: probe requires -a <addr>\n");
          return 1;
        }

      (void)vg_discover_state_load(&sum, NULL);
      sum.n_blocks = 0;

      ret = vg_reg_probe_slave(&sum, dev, CONFIG_VG_DISCOVER_BAUD,
                               addr, fc, CONFIG_VG_DISCOVER_REG_MAX);
      if (ret < 0)
        {
          fprintf(stderr, "vgdiscover: probe failed %d\n", ret);
          return 1;
        }

      printf("vgdiscover: probe addr=%u blocks=%d\n",
             (unsigned)addr, sum.n_blocks);
      for (int i = 0; i < sum.n_blocks; i++)
        {
          FAR struct vg_reg_block *b = &sum.blocks[i];

          printf("  fc=%u start=%u count=%u sample[0]=%u sample[1]=%u\n",
                 (unsigned)b->fc, (unsigned)b->start, (unsigned)b->count,
                 (unsigned)b->sample[0], (unsigned)b->sample[1]);
        }

      (void)vg_discover_state_save(&sum, NULL);
      return (sum.n_blocks > 0) ? 0 : 1;
    }

  if (strcmp(argv[1], "dump") == 0)
    {
      FAR const char *out = CONFIG_VG_DISCOVER_CANDIDATE_PATH;

      if (argc >= 4 && strcmp(argv[2], "-o") == 0)
        {
          out = argv[3];
        }

      if (vg_discover_state_load(&sum, NULL) != 0)
        {
          fprintf(stderr, "vgdiscover: no saved state — run scan/probe first\n");
          return 1;
        }

      vg_point_table_infer(&sum);
      ret = vg_point_table_write_candidate(&sum, out);
      if (ret != 0)
        {
          fprintf(stderr, "vgdiscover: dump failed %d\n", ret);
          return 1;
        }

      printf("vgdiscover: wrote %d points → %s\n", sum.n_points, out);
      (void)vg_discover_state_save(&sum, NULL);
      return 0;
    }

  if (strcmp(argv[1], "test-read") == 0)
    {
      uint8_t addr = 0;
      uint16_t reg = 0;
      uint16_t qty = 1;
      uint16_t vals[16];
      int opt;
      unsigned int i;

      optind = 2;
      while ((opt = getopt(argc, argv, "a:r:c:")) != ERROR)
        {
          switch (opt)
            {
              case 'a':
                addr = (uint8_t)strtol(optarg, NULL, 0);
                break;

              case 'r':
                reg = (uint16_t)strtol(optarg, NULL, 0);
                break;

              case 'c':
                qty = (uint16_t)strtol(optarg, NULL, 0);
                if (qty > 16)
                  {
                    qty = 16;
                  }
                break;

              default:
                usage(argv[0]);
                return 1;
            }
        }

      if (addr == 0)
        {
          fprintf(stderr, "vgdiscover: test-read requires -a\n");
          return 1;
        }

      ret = vg_discover_test_read(dev, CONFIG_VG_DISCOVER_BAUD,
                                  addr, reg, qty, vals);
      if (ret != 0)
        {
          fprintf(stderr, "vgdiscover: test-read failed %d\n", ret);
          return 1;
        }

      printf("vgdiscover: addr=%u reg=%u:", (unsigned)addr, (unsigned)reg);
      for (i = 0; i < qty; i++)
        {
          float s = vg_discover_decode_int16_scaled((int16_t)vals[i], 0.1f);

          printf(" [%u]=%u (%.1f)", (unsigned)(reg + i),
                 (unsigned)vals[i], (double)s);
        }

      printf("\n");
      return 0;
    }

  if (strcmp(argv[1], "apply") == 0)
    {
      bool confirm = false;
      int i;

      for (i = 2; i < argc; i++)
        {
          if (strcmp(argv[i], "--confirm") == 0)
            {
              confirm = true;
            }
        }

      if (vg_discover_state_load(&sum, NULL) != 0)
        {
          fprintf(stderr, "vgdiscover: no saved state — run dump first\n");
          return 1;
        }

      if (sum.n_points == 0)
        {
          vg_point_table_infer(&sum);
        }

      ret = vg_point_table_apply(&sum, CONFIG_VG_DISCOVER_POINTS_PATH,
                                 CONFIG_VG_CONFIG_BASEDIR, confirm);
      return (ret == 0) ? 0 : 1;
    }

  usage(argv[0]);
  return 1;
}

