# Stage1 LVGL HMI 板端验收（velaguard-lvgl @ COM3）。
#   powershell.exe -ExecutionPolicy Bypass -File scripts/stage1_lvgl_hmi_accept.ps1

param(
  [string]$ComPort = "COM3",
  [int]$Baud = 115200,
  [string]$Log = ""
)

$ErrorActionPreference = "Stop"
$script:pass = 0
$script:fail = 0

function Wait-Prompt {
  param([string]$Buf, [int]$TimeoutSec = 12)
  $deadline = (Get-Date).AddSeconds($TimeoutSec)
  while ((Get-Date) -lt $deadline) {
    if ($Buf -match "nsh>") { return $true }
    Start-Sleep -Milliseconds 120
  }
  return $false
}

function Send-Serial {
  param(
    [System.IO.Ports.SerialPort]$Port,
    [string]$Cmd,
    [int]$WaitSec = 20
  )
  $Port.DiscardInBuffer()
  $Port.WriteLine($Cmd)
  Start-Sleep -Milliseconds 800
  $buf = ""
  $deadline = (Get-Date).AddSeconds($WaitSec)
  while ((Get-Date) -lt $deadline) {
    if ($Port.BytesToRead -gt 0) { $buf += $Port.ReadExisting() }
    if (Wait-Prompt $buf 1) { break }
    Start-Sleep -Milliseconds 120
  }
  $block = "`n=== $Cmd ===`n$buf"
  Write-Output $block
  return @{ Text = $buf; Block = $block }
}

function Assert-Match {
  param([string]$Name, [string]$Hay, [string]$Pattern)
  if ($Hay -match $Pattern) {
    Write-Output "[PASS] $Name"
    $script:pass++
  } else {
    Write-Output "[FAIL] $Name (pattern: $Pattern)"
    $script:fail++
  }
}

$port = New-Object System.IO.Ports.SerialPort
$port.PortName = $ComPort
$port.BaudRate = $Baud
$port.ReadTimeout = 8000
$port.NewLine = "`n"
$logLines = New-Object System.Collections.Generic.List[string]

try {
  $port.Open()
  Start-Sleep -Seconds 6
  $boot = ""
  $bootDeadline = (Get-Date).AddSeconds(25)
  while ((Get-Date) -lt $bootDeadline) {
    if ($port.BytesToRead -gt 0) { $boot += $port.ReadExisting() }
    if ($boot -match "nsh>") { break }
    Start-Sleep -Milliseconds 200
  }
  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 80 }

  $r = Send-Serial $port "?" 8
  Assert-Match "vghmi in help" $r.Text "vghmi"

  $r = Send-Serial $port "vghmi &" 15
  Assert-Match "LVGL fbdev 480x272" $r.Text "xres: 480"
  Assert-Match "touchscreen open" $r.Text "touchscreen /dev/input0 open success"

  $r = Send-Serial $port "ps" 8
  Assert-Match "vghmi task" $r.Text "vghmi"

  Write-Output "`n=== Summary: pass=$($script:pass) fail=$($script:fail) ==="
  Write-Output "NOTE: 目视确认 LCD 显示 'VelaGuard HMI' 占位屏（本脚本无法自动验屏）。"
  if ($Log -ne "") {
    $logLines.Add("pass=$($script:pass) fail=$($script:fail)")
    Set-Content -LiteralPath $Log -Value ($logLines -join "`n") -Encoding UTF8
  }
  if ($script:fail -gt 0) { exit 1 }
  exit 0
}
finally {
  if ($port.IsOpen) { $port.Close() }
}

