$p = New-Object System.IO.Ports.SerialPort COM3, 115200
$p.ReadTimeout = 5000
$p.WriteTimeout = 3000
$p.DtrEnable = $true
$p.NewLine = "`n"
$p.Open()
Start-Sleep 2
while ($p.BytesToRead -gt 0) { [void]$p.ReadExisting() }
$p.WriteLine("vgdiscover scan -a 1-32")
$buf = ""
$deadline = (Get-Date).AddSeconds(180)
while ((Get-Date) -lt $deadline) {
  if ($p.BytesToRead -gt 0) {
    $chunk = $p.ReadExisting()
    $buf += $chunk
    Write-Host -NoNewline $chunk
  }
  if ($buf -match "found \d+ slave" -and $buf -match "nsh>") { break }
  Start-Sleep -Milliseconds 100
}
Write-Output ""
if ($buf -match "found (\d+) slave") {
  Write-Output "SUMMARY hits=$($Matches[1])/32"
}
$p.Close()

